#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import json
from pathlib import Path

PAYLOAD = ''
patch = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
path = Path("data/site-data.json")
data = json.loads(path.read_text(encoding="utf-8"))
data["version"] = patch["version"]
data["updated"] = patch["updated"]
data["themes"] = patch["themes"]
data["metrics"].update(patch["metrics"])
assert len(data["themes"]) == 10
assert len(data["metrics"]) == 88
for key, metric in data["metrics"].items():
    assert len(metric["rows"]) == 7, f"Copertura incompleta: {key}"
path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print("Dataset locale v1.2 ricostruito: 10 temi, 88 indicatori")
